quote:
									Str("service", svc).
									Str("endpoint_key", info.EndpointKey).
									Str("error", err.Error())).
									Msg("Failed to delete service endpoint with stored key")
								metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, svc, metrics.PodRegisterStatusEtcdCallFailed)
							} else {
								log.Info().Dict("custom_attributes", logger.Attrs().
									Str("status_code", string(logger.GALACTUS_POD_DEREGISTERED)).
									Str("pod_name", podInfo.Name).
									Str("pod_ip", podInfo.IP).
									Str("service", svc).
									Str("serviceID", serviceID)).
									Msg("Service endpoint deleted successfully using stored key")
								metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, svc, metrics.PodRegisterStatusDeleted)
								metrics.PodRegisterStatus.DeletePartialMatch(prometheus.Labels{"nexus_pod": podInfo.Name})
							}
						}
						c.addedPods.Delete(serviceID)
						removedFromAddedPods = true
					}
				} else {
					// state == EndpointStateDelete: Direct delete using stored endpoint keys.
					// Filter out successfully-deleted entries; store back only the failed ones
					// so retries only attempt genuinely-failed ports.
					var remaining []EndpointInfo
					for _, info := range infos {
						err := adapterV2.Delete(info.EndpointKey)
						if err != nil {
							remaining = append(remaining, info)
							multiErr = multierr.Append(multiErr, err)
							log.Error().Dict("custom_attributes", logger.Attrs().
								Str("status_code", string(logger.GALACTUS_POD_DEREGISTER_FAILED)).
								Str("pod_name", podInfo.Name).
								Str("pod_ip", podInfo.IP).
								Str("service", svc).
								Str("endpoint_key", info.EndpointKey).
								Str("error", err.Error())).
								Msg("Failed to delete service endpoint with stored key")
							metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, svc, metrics.PodRegisterStatusEtcdCallFailed)
						} else {
							log.Info().Dict("custom_attributes", logger.Attrs().
								Str("status_code", string(logger.GALACTUS_POD_DEREGISTERED)).
								Str("pod_name", podInfo.Name).
								Str("pod_ip", podInfo.IP).
								Str("service", svc).
								Str("serviceID", serviceID)).
								Msg("Service endpoint deleted successfully using stored key")
							metrics.DeletePodRegisterStatus(podInfo.Name)
						}
					}
					// Terminal-phase escalation accounting: increment only when
					// this pass actually removed a key (len(remaining) <
					// len(infos)), so the counter stays event-unit — one
					// increment per service per eviction/completion. On later
					// Sync passes over the retained terminal pod object,
					// addedPods no longer holds the serviceID, so this branch is
					// never re-entered.
					if escalatedFromTerminal && len(remaining) < len(infos) {
						metrics.TerminalPodEndpointsDeletedTotal.WithLabelValues(svc, string(podInfo.Phase)).Inc()
						log.Info().Dict("custom_attributes", logger.Attrs().
							Str("pod_name", podInfo.Name).
							Str("pod_ip", podInfo.IP).
							Str("namespace", podInfo.Namespace).
							Str("phase", string(podInfo.Phase)).
							Str("service", svc)).
							Msg("eventDeleteFunc: terminal-phase pod endpoint deleted (drain escalated to delete)")
					}
					if len(remaining) == 0 {
						c.addedPods.Delete(serviceID)
						removedFromAddedPods = true
					} else {
						c.addedPods.Store(serviceID, remaining)
					}
				}
			} else {
				// No stored endpoint info - pod was never registered or already deleted
				log.Debug().Dict("custom_attributes", logger.Attrs().
					Str("pod_name", podInfo.Name).
					Str("pod_ip", podInfo.IP).
					Str("serviceID", serviceID)).
					Msg("No stored endpoint info for serviceID, skipping deletion")
			}

			mu.Unlock()
			if removedFromAddedPods {
				c.addedPodsMu.Delete(serviceID)
			}
		}
	}

	// Dual-registration orphan scan: catches addedPods entries for this pod
	// whose service-name is NOT in the current svcs list. See
	// pruneOrphanEndpoints for the scan implementation. Transition scenarios
	// that produce orphans:
	//   1. Flag flip on delete: pod was dual-registered, allow-dual-registration
	//      was removed or set to "false" on the LRC, pod is now being deleted.
	//   2. LRC deletion: pod previously matched LRC with dual-write active, LRC
	//      was deleted, pod is now being deleted before LRCDeleteCallback resync
	//      reached it.
	//   3. Relaxed LRC legacy-name change on delete: the pod's annotation/
	//      K8s-Service name changed (or now matches the LRC application name,
	//      collapsing the dual-write) and the pod is deleted before a resync.
	//      For relaxed LRCs svcs is the authoritative current name set (LRC
	//      name plus mismatched legacy names), so pruning anything outside it
	//      is safe whether or not dual-write is active.
	// Skipped when:
	//   - Non-relaxed LRC with dual-write currently active → main loop covers both.
	//   - No LRC AND no svcs → existing len(svcs) == 0 fallback handles it.
	switch {
	case lrcConfig != nil:
		if utils.IsValidationRelaxed(lrcConfig.Annotations) {
			if err := c.pruneOrphanEndpoints(podInfo, adapterV2, svcs, "stale_name"); err != nil {
				multiErr = multierr.Append(multiErr, err)
			}
		} else if !utils.IsDualRegistrationEnabled(lrcConfig.Annotations) {
			if err := c.pruneOrphanEndpoints(podInfo, adapterV2, svcs, "flag_flip"); err != nil {
				multiErr = multierr.Append(multiErr, err)
			}
		}
	case len(svcs) > 0:
		if err := c.pruneOrphanEndpoints(podInfo, adapterV2, svcs, "lrc_deletion"); err != nil {
			multiErr = multierr.Append(multiErr, err)
		}
	}
	return multiErr
}

// pruneOrphanEndpoints removes addedPods entries for this pod whose service-name
// is NOT in currentSvcs, deleting the underlying etcd endpoints and the
// addedPods/addedPodsMu bookkeeping. Trigger is recorded as a metric label.
//
// Used by:
//   - eventDeleteFunc: cleanup on pod deletion when flag-flip or lrc-deletion
//     state could have produced orphans (G3 — the original use).
//   - eventUpdateFunc (forceRegister=true): cleanup after LRC-update or
//     LRC-resync re-registration where the new config's svcs set shrunk
//     relative to the old (e.g., allow-dual-registration flipped from "true"
//     to "false" — lrcSpecChanged returns false for annotation changes since
//     annotations aren't in .Spec, so the standard cleanup path doesn't fire).
//
// Performance: O(N) over total addedPods entries per invocation. The per-entry
// filter is two string comparisons (cheap). At current production scale
// (~thousands of entries, dozens of LRC-matched pods), microseconds per call.
// Consider an addedPodsByPod secondary index for O(1) lookup if scale grows 10x.
//
// Concurrency: sync.Map.Range is safe with concurrent Delete. The function does
// NOT acquire c.addedPodsLock per serviceID — concurrent re-add via
// eventAddFunc is handled gracefully (re-registration is idempotent).
func (c *Controller) pruneOrphanEndpoints(podInfo *PodInfo, adapterV2 etcd.AdapterV2Interface, currentSvcs []string, trigger string) error {
	svcSet := make(map[string]struct{}, len(currentSvcs))
	for _, s := range currentSvcs {
		svcSet[s] = struct{}{}
	}
	log.Debug().Dict("custom_attributes", logger.Attrs().
		Str("pod_name", podInfo.Name).
		Str("pod_ip", podInfo.IP).
		Str("namespace", podInfo.Namespace).
		Str("trigger", trigger).
		Strs("currentSvcs", currentSvcs)).
		Msg("pruneOrphanEndpoints: scan starting")

	var multiErr error
	orphansFound := 0
	orphansDeleted := 0
	orphansFailed := 0
	endpointsDeleted := 0

	c.addedPods.Range(func(key, value any) bool {
		serviceID, ok := key.(string)
		if !ok {
			return true
		}
		parts := strings.Split(serviceID, "/")
		infos, ok := value.([]EndpointInfo)
		if !ok {
			return true
		}
		if len(infos) == 0 || len(parts) < 4 || parts[2] != podInfo.Name || infos[0].Namespace != podInfo.Namespace {
			return true
		}
		orphanService := parts[0]

		if _, handled := svcSet[parts[0]]; handled {
			// Same-service entry: the service name is still current, so the whole
			// serviceID is NOT an orphan. But individual keys may still be stale by
			// ADDRESS — a CAST spot-VM in-place reboot gives the pod a new IP under
			// the same name, leaving the old-IP key registered as healthy. Prune
			// only the key(s) whose address is not one of the pod's current PodIPs,
			// and drop just those EndpointInfo entries (keeping the live-IP entry so
			// items 5/6 stay consistent). A key whose IP cannot be parsed is left
			// alone (fail-safe: never delete a key we cannot positively identify as
			// stale). When PodIPs is empty (transient informer state) we skip too.
			if len(podInfo.PodIPs) == 0 {
				return true
			}
			var remaining []EndpointInfo
			prunedAny := false
			for _, info := range infos {
				keyIP, err := utils.KeyToPodIP(info.EndpointKey)
				if err != nil || podInfo.ipInCurrentPodIPs(keyIP) {
					remaining = append(remaining, info)
					continue
				}
				// Stale-IP key for a still-current service: delete it. DeleteExact,
				// not Delete — the pod is alive and its live-IP sibling key shares
				// the container prefix, so the prefix Delete would wipe it too.
				orphansFound++
				if delErr := adapterV2.DeleteExact(info.EndpointKey); delErr != nil {
					orphansFailed++
					multiErr = multierr.Append(multiErr, delErr)
					remaining = append(remaining, info)
					log.Error().Dict("custom_attributes", logger.Attrs().
						Str("status_code", string(logger.GALACTUS_CLEAN_STALE_FAILED)).
						Str("pod_name", podInfo.Name).
						Str("pod_ip", podInfo.IP).
						Str("namespace", podInfo.Namespace).
						Str("trigger", trigger).
						Str("serviceID", serviceID).
						Str("orphanService", orphanService).
						Str("stale_ip", keyIP).
						Str("endpoint_key", info.EndpointKey).
						Str("error", delErr.Error())).
						Msg("pruneOrphanEndpoints: failed to delete stale-IP endpoint")
				} else {
					endpointsDeleted++
					orphansDeleted++
					prunedAny = true
					log.Info().Dict("custom_attributes", logger.Attrs().
						Str("status_code", string(logger.GALACTUS_CLEAN_STALE_REMOVED)).
						Str("pod_name", podInfo.Name).
						Str("pod_ip", podInfo.IP).
						Str("namespace", podInfo.Namespace).
						Str("trigger", trigger).
						Str("serviceID", serviceID).
						Str("orphanService", orphanService).
						Str("stale_ip", keyIP).
						Str("endpoint_key", info.EndpointKey).
						Strs("pod_ips", podInfo.PodIPs)).
						Msg("pruneOrphanEndpoints: deleted stale-IP endpoint")
					metrics.DualRegistrationOrphansCleanedTotal.WithLabelValues(trigger, orphanService).Inc()
				}
			}
			// Only rewrite addedPods when we actually pruned something. Removing the
			// stale EndpointInfo here (item 6) keeps addedPods tracking only the
			// pod's live endpoint key(s); the stale key was just deregistered above,
			// so it is not orphaned in etcd.
			if prunedAny {
				if len(remaining) == 0 {
					c.addedPods.Delete(serviceID)
					c.addedPodsMu.Delete(serviceID)
				} else {
					c.addedPods.Store(serviceID, remaining)
				}
			}
			return true
		}

		orphansFound++
		allKeysDeleted := true
		for _, info := range infos {
			if err := adapterV2.Delete(info.EndpointKey); err != nil {
				allKeysDeleted = false
				orphansFailed++
				multiErr = multierr.Append(multiErr, err)
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_CLEAN_STALE_FAILED)).
					Str("pod_name", podInfo.Name).
					Str("pod_ip", podInfo.IP).
					Str("namespace", podInfo.Namespace).
					Str("trigger", trigger).
					Str("serviceID", serviceID).
					Str("orphanService", orphanService).
					Str("endpoint_key", info.EndpointKey).
					Str("error", err.Error())).
					Msg("pruneOrphanEndpoints: failed to delete stale endpoint")
			} else {
				endpointsDeleted++
				log.Info().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_CLEAN_STALE_REMOVED)).
					Str("pod_name", podInfo.Name).
					Str("pod_ip", podInfo.IP).
					Str("namespace", podInfo.Namespace).
					Str("trigger", trigger).
					Str("serviceID", serviceID).
					Str("orphanService", orphanService).
					Str("endpoint_key", info.EndpointKey).
					Strs("currentSvcs", currentSvcs)).
					Msg("pruneOrphanEndpoints: deleted stale endpoint")
				metrics.DualRegistrationOrphansCleanedTotal.WithLabelValues(trigger, orphanService).Inc()
			}
		}
		if allKeysDeleted {
			orphansDeleted++
		}
		c.addedPods.Delete(serviceID)
		c.addedPodsMu.Delete(serviceID)
		return true
	})

	// Aggregate visibility: one log per invocation so operators can see scan
	// activity at a glance. Level varies by outcome — INFO when work was done,
	// DEBUG when no orphans found, ERROR if any delete failed.
	switch {
	case orphansFailed > 0:
		log.Error().Dict("custom_attributes", logger.Attrs().
			Str("status_code", string(logger.GALACTUS_CLEAN_STALE_FAILED)).
			Str("pod_name", podInfo.Name).
			Str("pod_ip", podInfo.IP).
			Str("namespace", podInfo.Namespace).
			Str("trigger", trigger).
			Int("orphansFound", orphansFound).
			Int("orphansDeleted", orphansDeleted).
			Int("orphansFailed", orphansFailed).
			Int("endpointsDeleted", endpointsDeleted)).
			Msg("pruneOrphanEndpoints: scan complete with errors")
	case orphansFound > 0:
		log.Info().Dict("custom_attributes", logger.Attrs().
			Str("status_code", string(logger.GALACTUS_CLEAN_STALE_REMOVED)).
			Str("pod_name", podInfo.Name).
			Str("pod_ip", podInfo.IP).
			Str("namespace", podInfo.Namespace).
			Str("trigger", trigger).
			Int("orphansFound", orphansFound).
			Int("orphansDeleted", orphansDeleted).
			Int("endpointsDeleted", endpointsDeleted)).
			Msg("pruneOrphanEndpoints: scan complete, orphans cleaned")
	default:
		log.Debug().Dict("custom_attributes", logger.Attrs().
			Str("pod_name", podInfo.Name).
			Str("pod_ip", podInfo.IP).
